  nachpruefung: null, rest_cent: n.rest_cent, schluessel: n.sperre_schluessel || n.eintrag_schluessel || '', lauf_id: n.lauf_id,
  anhang: '', zustand: { ergebnis: 'nichts', zeile: n.zeile }, eintrag: null }, x || {});
