const lief = (x) => { const v = $(x).isExecuted; if (typeof v !== 'boolean') throw new Error('Versand - isExecuted nicht verfuegbar'); return v; };
const n = lief('Sperre prüfen') ? $('Sperre prüfen').first().json : $('Entscheidung').first().json;
