  nachpruefung: null, rest_cent: n.rest_cent, schluessel: n.sperre_schluessel || n.eintrag_schluessel || '', lauf_id: n.lauf_id,
  anhang: '', zustand: { ergebnis: 'nichts', zeile: n.zeile }, eintrag: null }, x || {});
const zurueck = () => ({ schluessel: n.sperre_schluessel, aktion: 'zurueckgegeben', gmail_id: '', datum: n.stichtag });
const zustandFrei = () => (n.schritt === 'entwurf_ersetzen' ? { ergebnis: 'entwurf_verworfen', stufe: n.stufe, datum: n.stichtag, zeile: n.zeile,
  status: n.status_zahlstand } : { ergebnis: 'nichts', zeile: n.zeile });
const mit = (text) => (n.meldungen || []).concat([{ rechnungsnr: n.rechnungsnr, text }]);
const r = $input.first().json;
if (r.statusCode !== 204 && r.statusCode !== 200 && r.statusCode !== 404) {
  return [{ json: erg('gescheitert', { alarm: true, grund: 'Entwurf löschen abgelehnt, HTTP ' + r.statusCode }) }];
